    // makeTraceFrame sets up a traceFrame for a frame.
    traceFrame makeTraceFrame(uintptr_t gen, Frame f)
    {
        traceFrame frame = {};
        frame.PC = f.PC;

        auto fn = f.Function;
        auto maxLen = 1 << 10;
        if(len(fn) > maxLen)
        {
            fn = fn.make_slice(len(fn) - maxLen);
        }
        frame.funcID = rec::put(gocpp::recv(runtime::trace.stringTab[gen % 2]), gen, fn);
        frame.line = uint64_t(f.Line);
        auto file = f.File;
        if(len(file) > maxLen)
        {
            file = file.make_slice(len(file) - maxLen);
        }
        frame.fileID = rec::put(gocpp::recv(runtime::trace.stringTab[gen % 2]), gen, file);
        return frame;
    }

    // tracefpunwindoff returns true if frame pointer unwinding for the tracer is
    // disabled via GODEBUG or not supported by the architecture.
    bool tracefpunwindoff()
    {
        return debug.tracefpunwindoff != 0 || (goarch::ArchFamily != goarch::AMD64 && goarch::ArchFamily != goarch::ARM64);
    }

    // fpTracebackPCs populates pcBuf with the return addresses for each frame and
    // returns the number of PCs written to pcBuf. The returned PCs correspond to
    // "physical frames" rather than "logical frames"; that is if A is inlined into
    // B, this will return a PC for only B.
    int fpTracebackPCs(gocpp::unsafe_pointer fp, gocpp::slice<uintptr_t> pcBuf)
    {
        int i;
        for(i = 0; i < len(pcBuf) && fp != nullptr; i++)
        {
            // return addr sits one word above the frame pointer
            pcBuf[i] = *(uintptr_t*)(gocpp::unsafe_pointer(uintptr_t(fp) + goarch::PtrSize));
            // follow the frame pointer to the next one
            fp = gocpp::unsafe_pointer(*(uintptr_t*)(fp));
        }
        return i;
    }

