    // fpunwindExpand expands a call stack from pcBuf into dst,
    // returning the number of PCs written to dst.
    // pcBuf and dst should not overlap.
    //
    // fpunwindExpand checks if pcBuf contains logical frames (which include inlined
    // frames) or physical frames (produced by frame pointer unwinding) using a
    // sentinel value in pcBuf[0]. Logical frames are simply returned without the
    // sentinel. Physical frames are turned into logical frames via inline unwinding
    // and by applying the skip value that's stored in pcBuf[0].
    int fpunwindExpand(gocpp::slice<uintptr_t> dst, gocpp::slice<uintptr_t> pcBuf)
    {
        if(len(pcBuf) == 0)
        {
            return 0;
        }
        else
        if(len(pcBuf) > 0 && pcBuf[0] == logicalStackSentinel)
        {
            // pcBuf contains logical rather than inlined frames, skip has already been
            // applied, just return it without the sentinel value in pcBuf[0].
            return copy(dst, pcBuf.make_slice(1));
        }

        int n = {};
        auto lastFuncID = abi::FuncIDNormal;
        auto skip = pcBuf[0];
        auto skipOrAdd = [=](uintptr_t retPC) mutable -> bool
        {
            if(skip > 0)
            {
                skip--;
            }
            else
            if(n < len(dst))
            {
                dst[n] = retPC;
                n++;
            }
            return n < len(dst);
        };

        outer:
        for(auto [gocpp_ignored, retPC] : pcBuf.make_slice(1))
        {
            if(false) {
            outer_continue:
                continue;
            outer_break:
                break;
            }
            auto callPC = retPC - 1;
            auto fi = findfunc(callPC);
            if(! rec::valid(gocpp::recv(fi)))
            {
                // There is no funcInfo if callPC belongs to a C function. In this case
                // we still keep the pc, but don't attempt to expand inlined frames.
                if(auto more = skipOrAdd(retPC); ! more)
                {
                    goto outer_break;
                }
                continue;
            }

            auto [u, uf] = newInlineUnwinder(fi, callPC);
            for(; rec::valid(gocpp::recv(uf)); uf = rec::next(gocpp::recv(u), uf))
            {
                auto sf = rec::srcFunc(gocpp::recv(u), uf);
                if(sf.funcID == abi::FuncIDWrapper && elideWrapperCalling(lastFuncID))
                {
                }
                else
                // ignore wrappers
                if(auto more = skipOrAdd(uf.pc + 1); ! more)
                {
                    goto outer_break;
                }
                lastFuncID = sf.funcID;
            }
        }
        return n;
    }

    // startPCForTrace returns the start PC of a goroutine for tracing purposes.
    // If pc is a wrapper, it returns the PC of the wrapped function. Otherwise it
    // returns pc.
    uintptr_t startPCForTrace(uintptr_t pc)
    {
        auto f = findfunc(pc);
        if(! rec::valid(gocpp::recv(f)))
        {
            // may happen for locked g in extra M since its pc is 0.
            return pc;
        }
        auto w = funcdata(f, abi::FUNCDATA_WrapInfo);
        if(w == nullptr)
        {
            // not a wrapper
            return pc;
        }
        return rec::textAddr(gocpp::recv(f.datap), *(uint32_t*)(w));
    }

